  public function getMaxNumeroBanco($banco_id){
        $periodoActual=date("Y"); 
		$conexion = Propel::getConnection();	
		$consulta = "SELECT MAX(%s) AS max FROM %s ";
	    $sql = sprintf($consulta, DirectorioExternoPeer::BANCO_ID, DirectorioExternoPeer::TABLE_NAME);
		//************************************************************************************
        $sentencia = $conexion->prepare($sql);
        $sentencia->execute();
        $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
        return ($resultset->max + 1);
        //************************************************************************************
	}
	
  public function executeUpdate()
  {
	$currentFormCrear     = "COMUN_CREAR_DIRECTORIO";
	$this->verificaPrilegioCerrar($currentFormCrear);
	//***********************************************************************************
    $editando_directorio = false;
    $redirect_url = "";
    if (!$this->getRequestParameter('directorioexterno_id'))
    {
      $directorio_externo = new DirectorioExterno();
    }
    else
    {
      $directorio_externo = DirectorioExternoPeer::retrieveByPk($this->getRequestParameter('directorioexterno_id'));
      $directorio_externo_hist = $directorio_externo->toArray();
      $editando_directorio = true;
      $this->forward404Unless($directorio_externo);
    }
    //*******************************************************************************
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $directorio_externo->setUsuarioId($usuariologuiado);
    $directorio_externo->setCiudadId($this->getRequestParameter('ciudad_id'));
	$directorio_externo->setEntidadId($this->getRequestParameter('entidad_id') ? $this->getRequestParameter('entidad_id') : null);
    $directorio_externo->setTipoidentificacionId($this->getRequestParameter('tipoidentificacion_id') ? $this->getRequestParameter('tipoidentificacion_id') : null);
    //$directorio_externo->setTipopeticionarioId($this->getRequestParameter('tipopeticionario_id') ? $this->getRequestParameter('tipopeticionario_id') : null);
    $directorio_externo->setNombre(trim($this->getRequestParameter('nombre')));
    $directorio_externo->setDireccion(trim($this->getRequestParameter('direccion')));
    $directorio_externo->setFuncionario(trim($this->getRequestParameter('funcionario')));
    $directorio_externo->setCargo(trim($this->getRequestParameter('cargo')));
    $directorio_externo->setTelefono(trim($this->getRequestParameter('telefono')));
    $directorio_externo->setFax(trim($this->getRequestParameter('fax')));
    $directorio_externo->setEmail(trim($this->getRequestParameter('email')));
    $directorio_externo->setPrefijo(trim($this->getRequestParameter('prefijo')));
    $directorio_externo->setEsPublico(1);
	$directorio_externo->setNit(trim($this->getRequestParameter('nit')));
    $directorio_externo->setCodigoPostal(trim($this->getRequestParameter('codigo_postal')));		
	//*******************************************************************************
    if($this->getRequestParameter('directorioexterno_id') == ""){
       $directorio_externo->setContEdicion(0);
    }else{
       $directorio_externo->setContEdicion(1); 
    }
    //*******************************************************************************
    if($this->getUser()->getAttribute('es_banco','','banco_saliente')==1){      	
      $directorio_externo->setBancoId($this->getMaxNumeroBanco());
      $directorio_externo->setBancoAbreviatura($this->getRequestParameter('banco_abreviatura'));
      $directorio_externo->setBancoCodigo($this->getRequestParameter('banco_codigo'));	
      $directorio_externo->setEsBanco(1);
	}
    //*******************************************************************************
	if(!$this->getRequestParameter('directorioexterno_id')){        
		$existe_reg = $this->validarRegistro($this->getRequestParameter('nombre'),$this->getRequestParameter('funcionario'),$this->getRequestParameter('nit'));
		if($existe_reg <= 0){	
			$directorio_externo->save();
			$redirect_url = 'directorio_externo/show?directorioexterno_id='.$directorio_externo->getDirectorioexternoId().'&opcion='.$this->getRequestParameter('opcion').'&campoText='.$this->getRequestParameter('campoText').'&campoId='.$this->getRequestParameter('campoId');		
		}else{
			$redirect_url = 'directorio_externo/list?duplicado=1&nit='.trim($this->getRequestParameter('nit')).'&opcion='.$this->getRequestParameter('opcion').'&campoText='.$this->getRequestParameter('campoText').'&campoId='.$this->getRequestParameter('campoId');
		}
    }else{
	    $directorio_externo->save();
		$redirect_url = 'directorio_externo/show?directorioexterno_id='.$directorio_externo->getDirectorioexternoId().'&opcion='.$this->getRequestParameter('opcion').'&campoText='.$this->getRequestParameter('campoText').'&campoId='.$this->getRequestParameter('campoId');
    }
    //*******************************************************************************
    //inserta en historico el anterior
    if($editando_directorio){//solo si se esta editando el directorio
       $this->insertHistoricoDirectorio($directorio_externo->toArray(),$directorio_externo_hist);
    }
    //*******************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/'.$redirect_url);
  }

  public function executeSelectRemitenteActive()
  {
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
    $entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
    //**********************************************************************************************
    $currentForm = "directorio_externo/list";
    if($this->tienePrilegio($currentForm)){ return null; }
    //**********************************************************************************************
    $this->parametros = '';
    $this->parametros .= "&campoText=" .$this->campoText=$this->getRequestParameter('campoText');
    $this->parametros .= "&campoId=" .$this->campoId=$this->getRequestParameter('campoId');
    $this->parametros .= "&opcion=" .$this->opcion = $this->getRequestParameter('opcion');
    $modulo_id = trim($this->getRequestParameter('modulo_id'));    
    //**********************************************************************************************
    $c = new Criteria();
    $c->setDistinct();
    //**********************************************************************************************
    if(!$this->getUser()->checkPerm("COMUN_LISTAR_TODAS_ENTIDADES", $usuario_conectado)){   		        
      $c->add(DirectorioExternoPeer::ENTIDAD_ID,$entidad_conectado);
      $c->addOr(DirectorioExternoPeer::ENTIDAD_ID,null,Criteria::ISNULL);
    }
    //**********************************************************************************************
    if(!$this->getUser()->checkPerm("COMUN_LISTAR_TODOS_DIRECTORIOS", $usuario_conectado)){
      $c->add(DirectorioExternoPeer::ES_PUBLICO,TRUE);
    }
    //**********************************************************************************************
    $query = $_GET['q'];
    if (trim($query))
    {
        //$query = str_replace(" ",'%',$query);
        $c1 = $c->getNewCriterion(DirectorioExternoPeer::NOMBRE,'%'.$query.'%',Criteria::LIKE);
        $c2 = $c->getNewCriterion(DirectorioExternoPeer::FUNCIONARIO,'%'.$query.'%',Criteria::LIKE);
        $c3 = $c->getNewCriterion(DirectorioExternoPeer::NIT,'%'.$query.'%',Criteria::LIKE);
        $c1->addOr($c2);
        $c3->addOr($c1);
        $c->add($c3);
    }
    //**********************************************************************************************
    $c->addAscendingOrderByColumn(DirectorioExternoPeer::NOMBRE);
    //**********************************************************************************************
    $c->clearSelectColumns();
    $c->addSelectColumn(DirectorioExternoPeer::DIRECTORIOEXTERNO_ID);//0
    $c->addSelectColumn(DirectorioExternoPeer::NOMBRE);//1
    $c->addSelectColumn(DirectorioExternoPeer::NIT);//2
    //**********************************************************************************************
    $resultset = InteresadosPeer::doSelectStmt($c);
    //**********************************************************************************************
    $term_list = array();
    //**********************************************************************************************
	  while($list_data = $resultset->fetch()){
        $text_name = (trim($list_data[2]));
        $nuid_text = trim($list_data[1]) ? trim($list_data[1]) : "";
        $text_name = $nuid_text ? ($nuid_text." - ".$text_name) : $text_name;

        $avatar = sfConfig::get('base_simad').'/images/simad/ico_logo_users.png';
        $term_list[] = array("id" => $list_data[0], "text" => utf8_encode($text_name), "img" => $avatar);
    }
    //**********************************************************************************************
    $data_json = json_encode($term_list);
    //**********************************************************************************************
    $this->getResponse()->setContentType('application/json');      
    return $this->renderText($data_json);
  }

