  public function validatedRegistro($registro_id)
  {
    if($registro_id)
    {
  	 /****/////////////////////////////////////////*************////////////////////
     $cr = new Criteria();
  	 $cr->add(ComRecibidaPeer::DIRECTORIOEXTERNO_ID,$registro_id);
  	 $cre = ComRecibidaPeer::doCount($cr);
     /****/////////////////////////////////////////*************////////////////////
     
     /****/////////////////////////////////////////*************////////////////////
     $cs = new Criteria();
  	 $cs->add(ServicioPeer::DIRECTORIOEXTERNO_ID,$registro_id);
  	 $crs = ServicioPeer::doCount($cs);
     /****/////////////////////////////////////////*************////////////////////

     /****/////////////////////////////////////////*************////////////////////
     $ce = new Criteria();
  	 $ce->add(EnviadaDirectorioPeer::DIRECTORIOEXTERNO_ID,$registro_id);
  	 $crev = EnviadaDirectorioPeer::doCount($ce);
     /****/////////////////////////////////////////*************////////////////////
     if($cre == 0 && $crs == 0 && $crev == 0)
     {
        $conexion = Propel::getConnection();						    
        $delete = "DELETE DIRECTORIO_EXTERNO_HIST WHERE DIRECTORIOEXTERNO_ID=".$registro_id;    			  		  		   
        $sentencia = $conexion->prepare($delete);
        $sentencia->execute();
        //****************************************************************************************
	    $delete = "DELETE DIRECTORIO_EXTERNO WHERE DIRECTORIOEXTERNO_ID=".$registro_id;    			  		  		   
        $sentencia = $conexion->prepare($delete);
        $sentencia->execute();
        return true;
     }
     else
     {
        return false;
     }
    }
  }
  
