  public function validarRegistro($nomb,$func,$nit)
  {  	
    $c = new Criteria();
    $c->add(DirectorioExternoPeer::NOMBRE,trim($nomb));
    $c->add(DirectorioExternoPeer::ES_PUBLICO,true);
    $c->add(DirectorioExternoPeer::FUNCIONARIO,trim($func));
	//***********************************************************************
	if(trim($nit)){
		$c->add(DirectorioExternoPeer::NIT,trim($nit));
	}
	//***********************************************************************
    $valDir  = DirectorioExternoPeer::doCount($c);
    if($valDir > 0){ return 1; }else{ return 0; }
    //***********************************************************************
    $a = new Criteria();
	if(trim($nit)){
		$a->add(DirectorioExternoPeer::NIT,trim($nit));
	}else{
		$a->add(DirectorioExternoPeer::NOMBRE,trim($nomb));
	}
	//***********************************************************************
    $a->add(DirectorioExternoPeer::ES_PUBLICO,true);
    $valNit  = DirectorioExternoPeer::doCount($a);
    //***********************************************************************
    if($valNit > 0){ return 1; }else{ return 0; }
  }
